const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const search_bar = require('search_bar') 
const square_button = require('square_button') 
const share_invoice_via = require('share_invoice_via')

module.exports = send_invoice_modal

async function send_invoice_modal(opts = {}, { onClose, contacts = [] } = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    data: ondata,
    icons: iconject
  }

  let dricons = []
  let current_contacts = Array.isArray(contacts) ? contacts : []
  let contact_elements = []
  const selected_contacts = new Set()

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="send-to-container"> 
      <div class="contact-list-container">
        <div class="modal-header">
          <div class="contact-list-header">Send to</div>
          <div class="close-btn">x</div>
        </div>
        <div class="top-bar"></div>
      </div>
      <div class="contacts-container"></div>
      <div class="invoice-share-section"></div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const contacts_container = shadow.querySelector('.contacts-container')
  const top_bar = shadow.querySelector('.top-bar')
  const invoice_section = shadow.querySelector('.invoice-share-section')
  const close_icon = shadow.querySelector('.close-btn')

  const subs = await sdb.watch(onbatch)

  close_icon.addEventListener('click', () => {
    if (onClose) onClose()
  })

  if (subs.length > 0) {
    const search = await search_bar(subs[0], message => {
      if (message.type !== 'search') return
      const query = message.value.toLowerCase()
      contact_elements.forEach(item => {
        item.element.style.display = item.name.toLowerCase().includes(query) ? '' : 'none'
      })
    })
    const button = await square_button(subs[1])
    const invoice_share = await share_invoice_via(subs[2])
    top_bar.append(search)
    top_bar.append(button)  
    invoice_section.append(invoice_share)
  }

  el.updateContacts = function (nextContacts) {
    current_contacts = Array.isArray(nextContacts) ? nextContacts : []
    renderContacts()
  }

  renderContacts()

  return el

  function renderContacts() {
    contacts_container.replaceChildren()
    contact_elements = []

    if (current_contacts.length === 0) {
      const empty = document.createElement('div')
      empty.className = 'empty-contacts'
      empty.textContent = 'No contacts yet'
      contacts_container.append(empty)
      return
    }

    current_contacts.forEach((contact, index) => {
      const key = contact.id || contact.address || `${contact.name || 'contact'}-${index}`
      const row = document.createElement('button')
      row.type = 'button'
      row.className = 'contact-row'
      row.setAttribute('aria-pressed', selected_contacts.has(key) ? 'true' : 'false')

      const left = document.createElement('div')
      left.className = 'contact-left'

      const avatar = document.createElement('div')
      avatar.className = 'contact-avatar'
      const image = document.createElement('img')
      image.src = contact.avatar || ''
      image.alt = contact.name || 'Contact'
      avatar.append(image)

      const tick = document.createElement('div')
      tick.className = 'green-tick'
      tick.textContent = '\u2713'
      avatar.append(tick)

      const info = document.createElement('div')
      info.className = 'contact-info'
      const name = document.createElement('div')
      name.className = 'contact-name'
      name.textContent = contact.name || 'Unknown'
      info.append(name)

      left.append(avatar, info)
      row.append(left)

      const updateSelection = () => {
        const selected = selected_contacts.has(key)
        row.classList.toggle('selected', selected)
        row.setAttribute('aria-pressed', selected ? 'true' : 'false')
      }

      row.addEventListener('click', () => {
        if (selected_contacts.has(key)) selected_contacts.delete(key)
        else selected_contacts.add(key)
        updateSelection()
      })

      updateSelection()
      contacts_container.append(row)
      contact_elements.push({ element: row, name: contact.name || '' })
    })
  }

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  async function ondata(data) {
  }

  function iconject(data) {
    dricons = data
    close_icon.innerHTML = dricons[0]
  }
}

function fallback_module() {
  return {
    api,
    _: {
      'search_bar': { $: '' },
      'share_invoice_via': { $: ''},
      'square_button': { $: '' },
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const search_bar = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      0: {
      }
    }

    const square_button = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      1: {
      }
    }

    const share_invoice_via = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      2: {
      }
    }

    return {
      drive: {
        'icons/': {  
          'x.svg': { 
            '$ref': 'x.svg' 
          } 
        },
        'style/': {
          'send_invoice_modal.css': {
            '$ref': 'send_invoice_modal.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        search_bar,
        square_button,
        share_invoice_via
      }
    }
  }
}
